 <p class="footer-note">THREE ALLIES · THREE RIVALS · EVERY MOVE MATTERS</p>
 </main></div>
 <div class="overlay" id="overlay"><div class="modal" id="modal"></div></div>
 <script>
+const alliesSeed=[
+ {id:'moss',name:'Mossback',emoji:'🐢',type:'Bloom',hp:124,speed:5,moves:[['Vine Whip','Bloom',23],['Seed Burst','Bloom',29],['Root Slam','Stone',33]]},
+ {id:'cinder',name:'Cinderkit',emoji:'🦊',type:'Flame',hp:96,speed:9,moves:[['Ember Pounce','Flame',29],['Quick Spark','Volt',24],['Blazing Rush','Flame',37]]},
+ {id:'ripplet',name:'Ripplet',emoji:'🐸',type:'Tide',hp:108,speed:7,moves:[['Bubble Pop','Tide',25],['Splash Dash','Tide',31],['Static Snap','Volt',28]]}
+];
+const foesSeed=[
+ {id:'pebblit',name:'Pebblit',emoji:'🦔',type:'Stone',hp:112,speed:6,moves:[['Pebble Toss','Stone',25],['Bramble Roll','Bloom',27],['Boulder Bonk','Stone',34]]},
+ {id:'voltkit',name:'Voltkit',emoji:'🐿️',type:'Volt',hp:98,speed:10,moves:[['Zap Dash','Volt',28],['Thunder Flick','Volt',33],['Wild Pounce','Stone',31]]},
+ {id:'ashwing',name:'Ashwing',emoji:'🦉',type:'Flame',hp:116,speed:8,moves:[['Cinder Gust','Flame',26],['Sky Ember','Flame',32],['Talon Strike','Stone',35]]}
+];
+const typeColors={Bloom:'#9be28a',Flame:'#ff9b72',Tide:'#83d8f1',Volt:'#f4df77',Stone:'#d2bda0'};
+const strongAgainst={Flame:'Bloom',Bloom:'Tide',Tide:'Flame',Volt:'Tide',Stone:'Volt'};
+let allies,foes,round=1,orders={},busy=false,over=false,logEntries=[];
+const $=s=>document.querySelector(s);
+function fresh(seed){return seed.map(x=>({...x,max:x.hp,moves:x.moves.map(m=>({name:m[0],type:m[1],power:m[2]}))}));}
+function living(team){return team.filter(c=>c.hp>0)}
+function pct(c){return Math.max(0,c.hp/c.max*100)}
+function healthColor(p){return p<28?'#ff8069':p<55?'#f2ca65':'#d2f36b'}
+function bar(c){return `<div class="hp-track"><div class="hp-fill" style="width:${pct(c)}%;background:${healthColor(pct(c))}"></div></div>`}
+function renderArena(){
+ $('#playerArena').innerHTML=allies.map(c=>`<div class="beast ${c.hp<=0?'out':''}" id="arena-${c.id}"><div class="creature">${c.emoji}</div><div class="beast-name">${c.name}</div><div class="beast-meta">${c.type.toUpperCase()}</div>${bar(c)}<div class="hp-label">${Math.max(0,c.hp)} / ${c.max} HP</div></div>`).join('');
+ $('#foeArena').innerHTML=foes.map(c=>`<div class="beast ${c.hp<=0?'out':''}" id="arena-${c.id}"><div class="creature">${c.emoji}</div><div class="beast-name">${c.name}</div><div class="beast-meta">${c.type.toUpperCase()}</div>${bar(c)}<div class="hp-label">${Math.max(0,c.hp)} / ${c.max} HP</div></div>`).join('');
+ $('#round').textContent=round;$('#allyCount').textContent=`· ${living(allies).length} ACTIVE`;
+}
+function targetOptions(c){return living(foes).map(f=>`<option value="${f.id}" ${orders[c.id]?.target===f.id?'selected':''}>${f.name} · ${f.hp} HP</option>`).join('')||'<option>None</option>'}
+function renderTeam(){
+ $('#playerTeam').innerHTML=allies.map(c=>{const dead=c.hp<=0,order=orders[c.id]||{move:0,target:living(foes)[0]?.id};if(!dead&&!orders[c.id])orders[c.id]=order;
+ return `<article class="member ${dead?'fainted':''} ${!dead&&orders[c.id]?.chosen?'active-pick':''}"><div class="member-top"><div class="member-emoji">${c.emoji}</div><div style="min-width:0"><div class="member-name">${c.name}</div><div class="type-tag" style="color:${typeColors[c.type]}">${c.type} · SPD ${c.speed}</div></div></div><div class="member-hp"><span>${dead?'FAINTED':'HP'}</span><span>${Math.max(0,c.hp)} / ${c.max}</span></div>${bar(c)}${dead?'':`<div class="move-controls">${c.moves.map((m,i)=>`<button class="move-btn ${order.move===i?'selected':''}" data-id="${c.id}" data-move="${i}" title="${m.name} · ${m.type} · ${m.power} power">${m.name}</button>`).join('')}</div><select class="target-select" data-target="${c.id}" aria-label="Target for ${c.name}">${targetOptions(c)}</select>`}</article>`}).join('');
+ $('#playerTeam').querySelectorAll('.move-btn').forEach(b=>b.onclick=()=>{if(busy)return;const id=b.dataset.id;orders[id]={...orders[id],move:+b.dataset.move,chosen:true};renderTeam();renderOrders()});
+ $('#playerTeam').querySelectorAll('.target-select').forEach(s=>s.onchange=()=>{orders[s.dataset.target]={...orders[s.dataset.target],target:s.value};renderOrders()});
+}
+function renderOrders(){let ready=living(allies).filter(c=>orders[c.id]?.chosen).length;$('#orderCount').textContent=`${ready} / ${living(allies).length} READY`;
+ $('#orders').innerHTML=living(allies).map(c=>{const o=orders[c.id],m=c.moves[o?.move||0],t=foes.find(f=>f.id===o?.target)||living(foes)[0];return `<div class="order"><span><span class="order-icon">${c.emoji}</span>${c.name}</span><small>${o?.chosen?m.name+' → '+(t?.name||'—'):'choose a move'}</small></div>`}).join('')||'<div class="order">No allies left</div>';
+ $('#resolveBtn').disabled=busy||over||ready!==living(allies).length||ready===0;
+}
+function log(text,cls=''){logEntries.unshift(`<p class="${cls}">${text}</p>`);logEntries=logEntries.slice(0,8);$('#log').innerHTML=logEntries.join('')}
+function effectiveness(moveType,targetType){if(strongAgainst[moveType]===targetType)return 1.5;if(strongAgainst[targetType]===moveType)return .72;return 1}
+function floatAt(id,text){const el=$(`#arena-${id}`);if(!el)return;const n=document.createElement('div');n.className='float-text';n.textContent=text;el.appendChild(n);setTimeout(()=>n.remove(),950)}
+function pause(ms){return new Promise(r=>setTimeout(r,ms))}
+async function resolve(){if(busy||over)return;busy=true;renderOrders();$('#battleStatus').textContent='ROUND IN PROGRESS · WATCH THE WHOLE CREW';
+ const actions=[];
+ for(const c of living(allies)){const o=orders[c.id],m=c.moves[o?.move||0];actions.push({user:c,team:allies,targetTeam:foes,move:m,target:o?.target,player:true,speed:c.speed})}
+ for(const c of living(foes)){const available=c.moves.filter(m=>m.power>=28),m=available[Math.floor(Math.random()*available.length)]||c.moves[0],targets=living(allies);actions.push({user:c,team:foes,targetTeam:allies,move:m,target:targets[Math.floor(Math.random()*targets.length)]?.id,player:false,speed:c.speed})}
+ actions.sort((a,b)=>b.speed-a.speed||Math.random()-.5);
+ for(const a of actions){if(a.user.hp<=0)continue;let target=a.targetTeam.find(x=>x.id===a.target&&x.hp>0);if(!target)target=living(a.targetTeam).sort((x,y)=>x.hp-y.hp)[0];if(!target)continue;
+ const attackEl=$(`#arena-${a.user.id}`),moveType=a.move.type,mult=effectiveness(moveType,target.type),crit=Math.random()<.12,damage=Math.max(8,Math.round((a.move.power*(.82+Math.random()*.36)*mult*(crit?1.45:1))));
+ attackEl?.classList.add('swing');setTimeout(()=>attackEl?.classList.remove('swing'),480);await pause(170);
+ target.hp=Math.max(0,target.hp-damage);const targetEl=$(`#arena-${target.id}`);targetEl?.classList.add('hit');setTimeout(()=>targetEl?.classList.remove('hit'),390);floatAt(target.id,`−${damage}${crit?'!':''}`);
+ let extra=mult>1?' It hit hard!':mult<1?' Not very effective.':'';if(crit)extra+=' Critical hit!';const msg=`<strong>${a.user.name}</strong> used ${a.move.name} on ${target.name} for ${damage}.${extra}`;
+ log(msg,mult>1?'good':mult<1?'':'');renderArena();await pause(330);
+ }
+ round++;orders={};busy=false;renderArena();renderTeam();renderOrders();
+ if(!living(foes).length||!living(allies).length){over=true;const won=living(foes).length===0;$('#battleStatus').textContent=won?'SQUAD VICTORY':'SQUAD DEFEATED';showEnd(won)}else $('#battleStatus').textContent='YOUR TURN · PLAN ALL MOVES';
+}

