function showModal(icon,title,body,button,action,secondary=''){$('#modal').innerHTML=`<div class="modal-icon">${icon}</div><h2>${title}</h2><div>${body}</div><button class="resolve-btn" id="modalAction">${button}</button>${secondary?`<button class="quiet-btn" style="margin-top:9px" id="modalSecondary">${secondary}</button>`:''}`;$('#overlay').classList.remove('hidden');$('#modalAction').onclick=()=>{if(action)action();$('#overlay').classList.add('hidden')};if(secondary)$('#modalSecondary').onclick=()=>$('#overlay').classList.add('hidden')}
function showHow(){showModal('⚔️','Every ally. Every round.',`<div class="how-list"><b>01</b> Pick one move for <b>each living ally</b>—they all take a turn.<br><b>02</b> Choose who to target; attacks are aimed at the same time, so a fallen target gets redirected.<br><b>03</b> Faster creatures act first. Match elemental types for extra damage.<br><b>04</b> Defeat the rival squad before they take out yours.</div>`,'Got it',null)}
function showEnd(won){showModal(won?'🏆':'💫',won?'Full squad, full victory!':'Your squad needs a breather.',`<p>${won?'Every rival is down. Your whole crew fought as one.':'The rival crew took the round. Tune your targets and try a fresh matchup.'} <b style="color:var(--lime)">Rounds played: ${round-1}</b></p>`,'Play again',()=>resetGame())}
function resetGame(){allies=fresh(alliesSeed);foes=fresh(foesSeed);round=1;orders={};busy=false;over=false;logEntries=[];renderArena();renderTeam();renderOrders();$('#battleStatus').textContent='YOUR TURN · PLAN ALL MOVES';log('<strong>Rivals enter the field.</strong> Plan an order for every ally.')}
$('#resolveBtn').addEventListener('click',resolve);$('#howBtn').addEventListener('click',showHow);$('#resetBtn').addEventListener('click',()=>showModal('↻','Start a new match?','Your current battle will be cleared and both squads return at full strength.','New match',()=>resetGame(),'Keep battling'));
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!$('#overlay').classList.contains('hidden'))return;if(e.key==='Enter'&&!busy&&!over&&!$('#resolveBtn').disabled)resolve()});
resetGame();
</script>

